 printf("I64 high=%d low=%x offsets=%u,%u\n",i.high_word,i.low_word,(unsigned)offsetof(FPU_I64,low_word),(unsigned)offsetof(FPU_I64,high_word));
 ok=(a.sign==1&&a.exp==127&&a.mant==0x400000&&z.hiword.sign==1&&z.hiword.exp==1023&&z.hiword.mant_hi==0x80000&&z.mant_lo==0&&e.sign_exp.sign==1&&e.sign_exp.exp==16383&&e.mant_hi==0xc0000000&&e.mant_lo==0&&i.high_word==-2&&i.low_word==0x12345678);
